window.createTaxonomySettings=function(api){
  const M=TaxonomyModel,e=api.esc;let domain='projects',query='';
  const descriptions={projects:'用于整理项目，与决定初始模块的“项目模式”分开管理。',prompts:'按领域或使用场景整理提示词。',skills:'按能力用途整理收藏的 Skill。',agents:'按产品用途整理 AI 网站。',tags:'提示词、Skill 与 Agent 共用标签；改名与合并会一起更新。'};
  const dialog=document.createElement('dialog');dialog.id='taxonomy-editor';dialog.setAttribute('aria-labelledby','taxonomy-dialog-title');document.body.append(dialog);
  const fixed=n=>domain!=='tags'&&n==='未分类';
  function rows(){const all=M.list(api.getState(),domain),items=all.filter(i=>i.name.toLowerCase().includes(query.toLowerCase()));return items.map(i=>{const at=all.findIndex(x=>x.name===i.name);return `<div class="taxonomy-row"><div class="taxonomy-name"><strong>${e(i.name)}</strong><span class="taxonomy-state ${i.active?'':'is-inactive'}">${fixed(i.name)?'默认':i.active?'使用中':'已停用'}</span></div><span class="taxonomy-count">${i.count} 条内容</span><div class="taxonomy-order"><button data-tax-action="up" data-tax-name="${e(i.name)}" aria-label="上移 ${e(i.name)}" ${at===0?'disabled':''}>↑</button><button data-tax-action="down" data-tax-name="${e(i.name)}" aria-label="下移 ${e(i.name)}" ${at===all.length-1?'disabled':''}>↓</button></div><div class="taxonomy-actions">${fixed(i.name)?'<span class="meta">未选择分类时使用</span>':`<button class="text-button" data-tax-action="rename" data-tax-name="${e(i.name)}">改名</button><button class="text-button" data-tax-action="merge" data-tax-name="${e(i.name)}">合并</button><button class="text-button" data-tax-action="toggle" data-tax-name="${e(i.name)}">${i.active?'停用':'启用'}</button>${i.count===0?`<button class="text-button" data-tax-action="remove" data-tax-name="${e(i.name)}">删除</button>`:''}`}</div></div>`;}).join('')||'<div class="empty"><h3>没有匹配的选项</h3><p>换个关键词，或添加一个新选项。</p></div>';}
  function render(){return `<header class="projects-heading"><div><h1>工作台设置</h1></div></header><div class="settings-layout"><nav class="settings-nav" aria-label="设置分类">${Object.entries(M.domains).map(([key,label])=>`<button data-tax-domain="${key}" aria-pressed="${domain===key}" class="${domain===key?'active':''}"><span>${label}</span><small>${M.list(api.getState(),key).length}</small></button>`).join('')}<p>项目模块在各自项目内管理。任务和项目状态保留固定规则。</p></nav><section class="panel settings-panel"><div class="panel-head"><div><h2>${M.domains[domain]}</h2><p class="meta">${descriptions[domain]}</p></div><button class="button primary" data-tax-action="add">＋ 新增${domain==='tags'?'标签':'分类'}</button></div><div class="settings-toolbar"><label class="project-search"><input id="taxonomy-search" type="search" aria-label="搜索设置选项" placeholder="搜索名称" value="${e(query)}"></label><span class="meta">顺序会应用到日常选择与分类浏览</span></div><div class="taxonomy-table-heading" aria-hidden="true"><span>名称与状态</span><span>使用数量</span><span>排序</span><span>管理</span></div><div id="taxonomy-results">${rows()}</div><p class="settings-footnote">停用后，新内容不再选择该项；已有内容仍可查看。合并会统一归属，不会删除内容。所有设置随工作台备份保存。</p></section></div>`;}
  function refresh(){api.refresh();}
  function run(fn){try{fn(JSON.parse(JSON.stringify(api.getState())));}catch(err){return err.message;}return api.commit(fn)?'':'未能保存，请重试。';}
  function edit(action,source=''){
    const label=domain==='tags'?'标签':'分类',current=M.list(api.getState(),domain).find(i=>i.name===source),targets=M.list(api.getState(),domain).filter(i=>i.active&&i.name!==source);
    const title=({add:'新增',rename:'修改',merge:'合并',remove:'删除'})[action]+label;
    dialog.innerHTML=`<form><div class="dialog-head"><h2 id="taxonomy-dialog-title">${title}</h2><button class="close" type="button" data-tax-close aria-label="关闭设置编辑">×</button></div>${action==='merge'?`<p>将「${e(source)}」的 ${current?.count||0} 条内容合并到：</p><label class="field">目标${label}<select name="target" required><option value="">请选择目标</option>${targets.map(i=>`<option value="${e(i.name)}">${e(i.name)}</option>`).join('')}</select></label><p class="meta">原选项会移除；内容、关联关系和提示词历史版本保留。</p>`:action==='remove'?`<p>删除未使用的${label}「${e(source)}」？</p><p class="meta">如有历史版本仍在使用，将保留该项并提示停用。</p>`:`<label class="field">${label}名称<input name="name" maxlength="40" required value="${action==='rename'?e(source):''}" placeholder="例如：${domain==='projects'?'活动运营':domain==='tags'?'PPT':'课程设计'}"></label>${action==='rename'?`<p class="meta">${current?.count||0} 条内容及相关历史版本会同步改名。</p>`:''}`}<p class="error" role="alert"></p><div class="dialog-actions"><button class="button" type="button" data-tax-close>取消</button><button class="button primary">${action==='merge'?'确认合并':action==='remove'?'确认删除':'保存'}</button></div></form>`;
    dialog.querySelectorAll('[data-tax-close]').forEach(b=>b.onclick=()=>dialog.close());
    dialog.querySelector('form').onsubmit=ev=>{ev.preventDefault();const f=new FormData(ev.target),value=f.get('name')||f.get('target'),error=run(s=>{if(action==='add')M.add(s,domain,value);else if(action==='rename')M.rename(s,domain,source,value);else if(action==='merge')M.merge(s,domain,source,value);else M.remove(s,domain,source);});if(error){dialog.querySelector('[role=alert]').textContent=error;return;}dialog.close();query='';refresh();api.toast(action==='merge'?'已合并，关联内容已更新':'设置已保存');};dialog.showModal();dialog.querySelector('input,select')?.focus();
  }
  document.addEventListener('click',ev=>{const tab=ev.target.closest('[data-tax-domain]');if(tab){domain=tab.dataset.taxDomain;query='';refresh();return;}const button=ev.target.closest('[data-tax-action]');if(!button)return;const action=button.dataset.taxAction,source=button.dataset.taxName;if(['add','rename','merge','remove'].includes(action))return edit(action,source);const error=run(s=>action==='toggle'?M.toggle(s,domain,source):M.move(s,domain,source,action==='up'?-1:1));if(error)return api.toast(error);refresh();api.toast(action==='toggle'?'使用状态已更新':'顺序已更新');});
  document.addEventListener('input',ev=>{if(ev.target.id==='taxonomy-search'){query=ev.target.value;document.querySelector('#taxonomy-results').innerHTML=rows();}});
  return {render};
};
window.taxonomyCategoryOptions=function(state,domain,current=''){
  const e=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  return TaxonomyModel.choices(state,domain,current).map(i=>`<option value="${e(i.name)}" ${i.name===(current||'未分类')?'selected':''}>${e(i.name)}${i.active?'':'（已停用，保留原分类）'}</option>`).join('');
};
window.attachTaxonomyTagPicker=function(dialog,state){
  const field=dialog.querySelector('[name=tags]');if(!field)return;
  const box=document.createElement('details');box.className='taxonomy-tag-picker';const summary=document.createElement('summary');summary.textContent='选择已有标签';box.append(summary);const choices=document.createElement('div');box.append(choices);
  const sync=()=>{const selected=TaxonomyModel.split(field.value).map(t=>t.toLowerCase());for(const b of choices.querySelectorAll('button'))b.setAttribute('aria-pressed',selected.includes(b.textContent.toLowerCase()));};
  for(const tag of TaxonomyModel.choices(state,'tags')){const button=document.createElement('button');button.type='button';button.textContent=tag.name;button.onclick=()=>{const current=TaxonomyModel.split(field.value),found=current.some(t=>t.toLowerCase()===tag.name.toLowerCase());field.value=(found?current.filter(t=>t.toLowerCase()!==tag.name.toLowerCase()):[...current,tag.name]).join('，');sync();};choices.append(button);}
  if(!choices.childElementCount){const hint=document.createElement('p');hint.className='meta';hint.textContent='可在上方输入新标签，保存后会加入标签设置。';choices.append(hint);}field.closest('label').after(box);field.addEventListener('input',sync);sync();
};
